import { render, screen, act } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'

// mock SphereCanvas since it needs webgl
vi.mock('@/components/sphere/SphereCanvas', () => ({
  SphereCanvas: ({ onClick }: { onClick?: () => void }) => (
    <div data-testid="sphere-canvas" onClick={onClick} />
  ),
}))

// mock motion to avoid animation complexity in tests
vi.mock('motion/react', () => ({
  motion: {
    div: ({
      children,
      ...props
    }: React.HTMLAttributes<HTMLDivElement> & { layout?: boolean }) => {
      const { ...rest } = props
      // filter out motion-specific props
      const htmlProps = Object.fromEntries(
        Object.entries(rest).filter(
          ([key]) =>
            !key.startsWith('animate') &&
            !key.startsWith('initial') &&
            !key.startsWith('exit') &&
            !key.startsWith('transition') &&
            !key.startsWith('layout') &&
            key !== 'layout'
        )
      )
      return <div {...htmlProps}>{children}</div>
    },
  },
  AnimatePresence: ({ children }: { children: React.ReactNode }) => (
    <>{children}</>
  ),
}))

import { PortfolioShell } from '@/components/layout/PortfolioShell'

describe('PortfolioShell', () => {
  beforeEach(() => {
    vi.useFakeTimers()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('starts in landing state', () => {
    render(<PortfolioShell />)
    expect(screen.getByText('mtmrfoz')).toBeInTheDocument()
    expect(screen.getByTestId('sphere-canvas')).toBeInTheDocument()
  })

  it('does not show nav in landing state', () => {
    render(<PortfolioShell />)
    expect(screen.queryByRole('navigation')).not.toBeInTheDocument()
  })

  it('transitions to content state after 3.5s', async () => {
    render(<PortfolioShell />)

    // still in landing state
    expect(screen.queryByRole('navigation')).not.toBeInTheDocument()

    // advance past auto-transition
    await act(async () => {
      vi.advanceTimersByTime(3600)
    })

    expect(screen.getByRole('navigation')).toBeInTheDocument()
  })

  it('transitions early on sphere click', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime })
    render(<PortfolioShell />)

    await user.click(screen.getByTestId('sphere-canvas'))

    expect(screen.getByRole('navigation')).toBeInTheDocument()
  })

  it('shows footer in both states', async () => {
    render(<PortfolioShell />)
    expect(screen.getByText(/2026/)).toBeInTheDocument()

    await act(async () => {
      vi.advanceTimersByTime(3600)
    })

    expect(screen.getByText(/2026/)).toBeInTheDocument()
  })
})

