// mock next/dynamic to render components synchronously
vi.mock('next/dynamic', () => ({
  default: (loader: () => Promise<{ default: React.ComponentType }>) => {
    let Component: React.ComponentType | null = null
    // resolve synchronously in test env since all imports are mocked
    const promise = loader()
    promise.then((mod) => {
      Component = mod.default
    })
    // force microtask flush
    return function DynamicComponent(props: Record<string, unknown>) {
      // in vitest with fake timers, the promise may not have resolved yet
      // so we use a wrapper that re-renders after promise resolves
      const [, setState] = (await import('react')).then ? [null, () => {}] : [null, () => {}]
      if (!Component) return null
      return <Component {...props} />
    }
  },
}))

